'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'

/**
 * Item: one row of a list. The thing almost every screen repeats: a person, a file, a project,
 * a setting, a search result, a notification. Left to right:
 *
 * - `icon` in a 32px muted tile (28 at sm), or `media` as it is (an Avatar, a thumbnail);
 * - `title` (13px medium) over `description` (13px muted), each on one line, cut with an ellipsis;
 *   `children` go under them for anything longer (Chips, a Progress);
 * - `meta` on the right in muted 13px: a time, a size, a Badge, a Kbd;
 * - `actions` at the far right: Buttons, a Switch, a DropdownMenu `⋯`.
 *
 * With `href` (or `onClick`) the row is a link (or a button) and the whole row is its target,
 * with a hover and a focus ring; `actions` stay their own controls on top of it. `selected`
 * marks the current row. Rows go in a `List`, or stand alone with `variant="outline"`.
 */
export interface ItemProps extends Omit<React.ComponentProps<'div'>, 'title' | 'onClick'> {
  title: React.ReactNode
  description?: React.ReactNode
  /** A glyph shown in a muted tile. */
  icon?: React.ReactNode
  /** Shown as is, in place of the tile: an Avatar, an image. */
  media?: React.ReactNode
  meta?: React.ReactNode
  actions?: React.ReactNode
  href?: string
  /** Link target, e.g. `_blank`. */
  target?: string
  onClick?: React.MouseEventHandler<HTMLButtonElement>
  selected?: boolean
  disabled?: boolean
  size?: 'sm' | 'md'
  /** `outline` draws a card border, for a row on its own. Rows in a List take the List's look. */
  variant?: 'plain' | 'outline'
}

interface ListContextValue {
  variant: 'plain' | 'divided' | 'card'
  size: 'sm' | 'md'
}

const ListContext = React.createContext<ListContextValue | null>(null)

export function Item({
  title,
  description,
  icon,
  media,
  meta,
  actions,
  href,
  target,
  onClick,
  selected = false,
  disabled = false,
  size: ownSize,
  variant = 'plain',
  className,
  children,
  ...props
}: ItemProps) {
  const list = React.useContext(ListContext)
  const size = ownSize ?? list?.size ?? 'md'
  const sm = size === 'sm'
  const interactive = (href !== undefined || onClick !== undefined) && !disabled
  // An li in a List; the ref types differ only by element, so it's typed as the div it is alone.
  const Root = (list ? 'li' : 'div') as 'div'
  // Edge to edge inside a divided list or a card, rounded on its own.
  const flush = list?.variant === 'divided' || list?.variant === 'card'

  // The title is the link or button; its ::after stretches over the row, so the row is the target.
  const target_ = 'sa:outline-none sa:after:absolute sa:after:inset-0'
  const titleText = <span className="sa:block sa:truncate">{title}</span>
  const titleNode = href !== undefined && !disabled ? (
    <a href={href} target={target} rel={target === '_blank' ? 'noopener noreferrer' : undefined} data-slot="item-target" aria-current={selected ? 'page' : undefined} className={cn(target_, 'sa:no-underline sa:text-inherit')}>
      {titleText}
    </a>
  ) : onClick && !disabled ? (
    <button type="button" data-slot="item-target" aria-pressed={selected || undefined} onClick={onClick} className={cn(target_, 'sa:block sa:w-full sa:cursor-pointer sa:text-left')}>
      {titleText}
    </button>
  ) : (
    titleText
  )

  return (
    <Root
      data-slot="item"
      data-size={size}
      data-selected={selected || undefined}
      data-disabled={disabled || undefined}
      className={cn(
        'sa:relative sa:flex sa:min-w-0 sa:items-center',
        sm ? 'sa:min-h-10 sa:gap-2.5 sa:px-2 sa:py-1.5' : 'sa:min-h-14 sa:gap-3 sa:px-3 sa:py-2.5',
        flush ? (list?.variant === 'card' ? (sm ? 'sa:px-3' : 'sa:px-4') : 'sa:px-0') : 'sa:rounded-lg',
        variant === 'sa:outline' && !list && 'sa:border sa:border-border-default sa:bg-bg-card sa:[box-shadow:0_1px_2px_0_var(--effect-shadow-xs)]',
        'sa:transition-colors sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
        interactive && 'sa:hover:bg-bg-hover',
        interactive && flush && list?.variant === 'divided' && 'sa:hover:bg-transparent sa:[&:hover_[data-slot=item-title]]:underline',
        selected && 'sa:bg-bg-selected sa:hover:bg-bg-selected',
        // The focus ring of the stretched link, drawn on the row.
        'sa:has-[[data-slot=item-target]:focus-visible]:[box-shadow:inset_0_0_0_2px_var(--action-focus-ring)]',
        disabled && 'sa:opacity-50',
        className,
      )}
      {...props}
    >
      {media ? (
        <span className="sa:flex sa:shrink-0 sa:items-center">{media}</span>
      ) : icon ? (
        <span
          aria-hidden
          className={cn(
            'sa:grid sa:shrink-0 sa:place-items-center sa:rounded-lg sa:bg-bg-muted sa:text-text-muted sa:[&_svg]:size-icon-size sa:[&_svg]:[stroke-width:1.875]',
            sm ? 'sa:size-7' : 'sa:size-8',
          )}
        >
          {icon}
        </span>
      ) : null}
      <div className="sa:min-w-0 sa:flex-1">
        <div data-slot="item-title" className="sa:text-sm sa:leading-5 sa:font-medium sa:text-text-default sa:underline-offset-[3px]">
          {titleNode}
        </div>
        {description && <p className="sa:truncate sa:text-sm sa:leading-5 sa:text-text-muted">{description}</p>}
        {children && <div className="sa:mt-1.5">{children}</div>}
      </div>
      {meta && <div className="sa:shrink-0 sa:text-sm sa:text-text-muted sa:tabular-nums">{meta}</div>}
      {actions && (
        // Above the stretched target, so they stay their own controls.
        <div className="sa:relative sa:z-10 sa:flex sa:shrink-0 sa:items-center sa:gap-1">{actions}</div>
      )}
    </Root>
  )
}

/**
 * List: Items under each other. `plain` (default) keeps them apart by 2px with rounded hovers,
 * for menus of links and search results; `divided` runs a rule between rows, edge to edge, for
 * feeds and settings; `card` puts the divided rows in a bordered card. `size` is passed to every
 * Item. It's a `ul`; give it an `aria-label` when the heading above doesn't name it.
 */
export interface ListProps extends React.ComponentProps<'ul'> {
  variant?: 'plain' | 'divided' | 'card'
  size?: 'sm' | 'md'
}

export function List({ variant = 'plain', size = 'md', className, ...props }: ListProps) {
  const context = React.useMemo(() => ({ variant, size }), [variant, size])
  return (
    <ListContext.Provider value={context}>
      <ul
        role="list"
        data-slot="list"
        data-variant={variant}
        className={cn(
          'sa:m-0 sa:flex sa:w-full sa:list-none sa:flex-col sa:p-0',
          variant === 'plain' && 'sa:gap-0.5',
          variant !== 'plain' && 'sa:divide-y sa:divide-border-default',
          variant === 'card' &&
            'sa:overflow-hidden sa:rounded-xl sa:border sa:border-border-default sa:bg-bg-card sa:[box-shadow:0_1px_2px_0_var(--effect-shadow-xs)]',
          className,
        )}
        {...props}
      />
    </ListContext.Provider>
  )
}
